// App members. Read-only scan -> explicit copy -> verified gallery binding.
std::thread copyMigrationThread;std::atomic_bool copyMigrationCancel{false},copyMigrationActive{false};bool copyMigrationBusy=false;uint64_t copyMigrationSerial=0;json copyMigrationPlan=json::object();
void resetCopyMigration(){copyMigrationCancel=true;++copyMigrationSerial;copyMigrationBusy=false;copyMigrationPlan=json::object();}
std::string copyMigrationContext(){return sha256(json{{"scope",store->workspaceScope},{"channel",store->active},{"mode",hardcore()?"hardcore":"safe"}}.dump());}
std::wstring copyMigrationSummary(){if(copyMigrationPlan.empty())return L"먼저 원본을 선택해 검사하세요.";auto& plan=copyMigrationPlan;return L"원본  · "+wide(str(plan,"source"))+L"\nJSON  · "+wide(str(plan,"metadata_source"))+L"\n대상  · "+wide(str(plan,"target"))+L"\n이미지 "+std::to_wstring(plan.value("images",size_t(0)))+L"장 / 파일 "+std::to_wstring(plan["entries"].size())+L"개 / "+std::to_wstring(plan.value("bytes",uint64_t(0))/1024/1024)+L" MiB\n소유 기록 없는 이미지 "+std::to_wstring(plan.value("unknown_owners",uint64_t(0)))+L"장\n"+(!str(plan,"source_scope").empty()&&str(plan,"source_scope")!=store->workspaceScope?L"원본 계정 기록이 다릅니다. 현재 계정으로의 명시적 귀속 확인이 필요합니다.":L"현재 계정·채널에 사본을 연결합니다.");}
void beginCopyMigration(const std::string& action,const json& arguments){if(copyMigrationBusy||copyMigrationActive||migrationRunning)throw std::runtime_error("현재 이관 작업을 마치거나 중지하세요.");if(store->workspaceScope.empty())throw std::runtime_error("로그인한 계정에서 이관하세요.");if(copyMigrationThread.joinable())copyMigrationThread.join();auto scope=store->workspaceScope,channel=store->active,context=copyMigrationContext();auto root=store->root;auto serial=++copyMigrationSerial;copyMigrationCancel=false;copyMigrationBusy=true;copyMigrationActive=true;auto* target=engine;status=action=="scan"?L"이관 원본 검사 중…":action=="copy"?L"사본 복사 중…":L"사본 롤백 중…";
try{copyMigrationThread=std::thread([this,scope,channel,context,root,serial,target,action,arguments]{json reply={{"scope",scope},{"channel",channel},{"context",context},{"serial",serial},{"action",action}};ULONGLONG last=0;std::string previousStage;auto progress=[&](const std::string& stage,uint64_t done,uint64_t total){auto now=GetTickCount64();if(stage==previousStage&&now-last<200&&done!=total)return;last=now;previousStage=stage;target->event({"copy_migration_progress","","",{{"scope",scope},{"channel",channel},{"context",context},{"serial",serial},{"stage",stage},{"done",done},{"total",total}}});};try{if(action=="scan")reply["plan"]=migrationCopyPlan(wide(str(arguments,"source")),wide(str(arguments,"destination")),wide(str(arguments,"metadata_source")),scope,channel,str(arguments,"mode"),copyMigrationCancel,progress);else if(action=="copy")reply["binding"]=migrationCopyApply(arguments,root,copyMigrationCancel,progress);else if(action=="rollback")reply["rollback"]=migrationCopyRollback(arguments,root,scope,channel,copyMigrationCancel,progress);else if(action=="attach")reply["binding"]=verifyMigration(wide(str(arguments,"target")),scope,channel,copyMigrationCancel,[&](size_t done,size_t total){progress("재검사",done,total);});else if(action=="history"){json rows=json::array();auto folder=root/"config/migration-history";if(fs::is_directory(fs::path(extendedWindowsPath(folder))))for(auto& file:fs::directory_iterator(fs::path(extendedWindowsPath(folder)))){if(copyMigrationCancel)throw std::runtime_error("이관 기록 조회를 중지했습니다.");if(rows.size()>=200)break;if(file.path().extension()!=L".json")continue;try{auto row=copyReadJson(file.path(),65536);if(str(row,"scope")==scope&&str(row,"channel")==channel&&storageId(str(row,"transaction"),32))rows.push_back(row);}catch(const std::exception&){}}reply["history"]=rows;}else throw std::runtime_error("이관 작업 종류 오류");}catch(const std::exception& error){reply["error"]=userError(error.what());}copyMigrationActive=false;target->event({"copy_migration_ready","","",reply});});}catch(...){copyMigrationActive=false;copyMigrationBusy=false;throw std::runtime_error("이관 작업을 시작하지 못했습니다.");}}
void inspectCopyMigration(){auto source=pickFolder(hwnd,L"현재 계정으로 이관할 원본 이미지 폴더");if(source.empty())return;auto destination=pickFolder(hwnd,L"사본을 새로 만들 대상 폴더");if(destination.empty())return;auto images=fs::path(source),metadata=images;auto root=migrationSafePath(images);auto attrs=[&](const fs::path& path){return GetFileAttributesW(extendedWindowsPath(path).c_str());};if((attrs(root/".snuw-output.json")!=INVALID_FILE_ATTRIBUTES||attrs(root/".snuw-layout-migration.json")!=INVALID_FILE_ATTRIBUTES)&&attrs(root/"images")!=INVALID_FILE_ATTRIBUTES&&attrs(root/"metadata")!=INVALID_FILE_ATTRIBUTES){images=root/"images";metadata=root/"metadata";}else if(MessageBoxW(hwnd,L"JSON 설명 파일이 이미지와 다른 폴더에 있습니까?",L"JSON 원본 폴더",MB_YESNO|MB_ICONQUESTION)==IDYES){auto selected=pickFolder(hwnd,L"이미지와 같은 상대 경로의 JSON 원본 폴더");if(selected.empty())return;metadata=selected;}copyMigrationPlan=json::object();beginCopyMigration("scan",{{"source",utf8(images.wstring())},{"destination",utf8(fs::path(destination).wstring())},{"metadata_source",utf8(metadata.wstring())},{"mode",hardcore()?"hardcore":"safe"}});}
void applyCopyMigration(){if(copyMigrationPlan.empty()||str(copyMigrationPlan,"user")!=store->workspaceScope||str(copyMigrationPlan,"channel")!=store->active||str(copyMigrationPlan,"mode")!=(hardcore()?"hardcore":"safe"))throw std::runtime_error("현재 계정·채널·모드로 다시 검사하세요.");auto bindings=store->state.value("_gallery_migrations",json::array());if(!bindings.is_array()||bindings.size()>=16)throw std::runtime_error("채널당 이관 연결은 16개까지 가능합니다.");auto text=copyMigrationSummary()+L"\n\n선택한 자료가 본인 소유이고 현재 모드에 적합한지 확인했습니까?\n확인하면 현재 계정·채널로 사본을 복사합니다. 원본은 변경하지 않습니다.";if(MessageBoxW(hwnd,text.c_str(),L"이관 사본 복사 확인",MB_YESNO|MB_ICONQUESTION)!=IDYES)return;save();atomicWrite(store->root/"config/migration-index-backups"/(id()+".json"),json{{"scope",store->workspaceScope},{"channel",store->active},{"bindings",bindings},{"created",timestamp()}}.dump(2));beginCopyMigration("copy",copyMigrationPlan);}
void copyMigrationReply(const Event& event){if(event.data.value("serial",uint64_t(0))!=copyMigrationSerial)return;if(event.kind=="copy_migration_ready"){if(copyMigrationThread.joinable())copyMigrationThread.join();copyMigrationBusy=false;}if(str(event.data,"scope")!=store->workspaceScope||str(event.data,"channel")!=store->active||str(event.data,"context")!=copyMigrationContext())return;if(event.kind=="copy_migration_progress"){status=L"이관 "+wide(str(event.data,"stage"))+L" · "+std::to_wstring(event.data.value("done",uint64_t(0)))+L" / "+std::to_wstring(event.data.value("total",uint64_t(0)));return;}if(!str(event.data,"error").empty()){status=wide(str(event.data,"error"));return;}auto action=str(event.data,"action");if(action=="scan"){copyMigrationPlan=event.data["plan"];status=L"이관 검사 완료 · 이관 관리에서 결과를 확인하고 사본 복사를 선택하세요.";return;}if(action=="history"){showCopyMigrationHistory(event.data.value("history",json::array()).get<std::vector<json>>());return;}if(action=="copy"||action=="attach"){auto binding=event.data["binding"];migrationRecord(wide(str(binding,"target")),store->workspaceScope,store->active,binding);auto& list=store->state["_gallery_migrations"];if(!list.is_array())list=json::array();bool exists=false;for(auto& old:list)exists|=str(old,"transaction")==str(binding,"transaction");if(!exists&&list.size()<16)list.push_back(binding);store->save();if(action=="copy")copyMigrationPlan=json::object();scan();status=action=="copy"?L"사본 복사·SHA 검증·갤러리 연결 완료":L"검증 후 갤러리 연결 완료";return;}if(action=="rollback"){auto result=event.data["rollback"];auto& bindings=store->state["_gallery_migrations"];if(bindings.is_array())bindings.erase(std::remove_if(bindings.begin(),bindings.end(),[&](const json& row){return str(row,"transaction")==str(result,"transaction");}),bindings.end());migrationFiles.clear();migrationCacheKey.clear();selected.clear();preview.Reset();store->save();scan();status=L"롤백 · 사본 삭제 "+std::to_wstring(result.value("removed",uint64_t(0)))+L"개 / 수정·잠김 파일 보존 "+std::to_wstring(result.value("preserved",uint64_t(0)))+L"개";}}
void showCopyMigrationHistory(std::vector<json> rows){std::sort(rows.begin(),rows.end(),[](const json& a,const json& b){return str(a,"created")>str(b,"created");});HMENU menu=CreatePopupMenu();for(size_t i=0;i<rows.size();i++){auto title=wide(str(rows[i],"created"))+L" · "+wide(str(rows[i],"state"));AppendMenuW(menu,MF_STRING,i+1,title.c_str());}if(rows.empty())AppendMenuW(menu,MF_STRING|MF_GRAYED,0,L"현재 채널의 복사 기록이 없습니다.");POINT point;GetCursorPos(&point);int choice=TrackPopupMenu(menu,TPM_RETURNCMD|TPM_NONOTIFY,point.x,point.y,0,hwnd,nullptr);DestroyMenu(menu);if(choice<=0||size_t(choice)>rows.size())return;auto row=rows[choice-1];HMENU actions=CreatePopupMenu();AppendMenuW(actions,MF_STRING,1,L"기록 보기");AppendMenuW(actions,MF_STRING|(!sheetHash(str(row,"manifest_hash"))||str(row,"state")=="rolled_back"?MF_GRAYED:0),2,L"검증 후 갤러리 연결");AppendMenuW(actions,MF_STRING|(!sheetHash(str(row,"manifest_hash"))||str(row,"state")=="rolled_back"?MF_GRAYED:0),3,L"원본과 동일한 사본만 롤백");choice=TrackPopupMenu(actions,TPM_RETURNCMD|TPM_NONOTIFY,point.x,point.y,0,hwnd,nullptr);DestroyMenu(actions);if(choice==1){auto text=L"원본 · "+wide(str(row,"source"))+L"\n대상 · "+wide(str(row,"target"))+L"\n상태 · "+wide(str(row,"state"))+L"\n"+wide(str(row,"message"));MessageBoxW(hwnd,text.c_str(),L"이관 기록",MB_OK|MB_ICONINFORMATION);}else if(choice==2){if(MessageBoxW(hwnd,L"기록의 폴더를 다시 검사한 뒤 연결할까요?",L"이관 연결",MB_YESNO|MB_ICONQUESTION)==IDYES)beginCopyMigration("attach",row);}else if(choice==3&&MessageBoxW(hwnd,L"원본이 그대로 존재하고 SHA가 같은 사본만 삭제할까요?\n수정·새 파일·잠긴 파일은 보존하며 갤러리 연결은 해제합니다.",L"사본 롤백",MB_YESNO|MB_ICONQUESTION)==IDYES){atomicWrite(store->root/"config/migration-index-backups"/(id()+".json"),json{{"scope",store->workspaceScope},{"channel",store->active},{"bindings",store->state.value("_gallery_migrations",json::array())},{"created",timestamp()}}.dump(2));beginCopyMigration("rollback",row);}}
void migrationManagerMenu(){HMENU menu=CreatePopupMenu();bool busy=copyMigrationBusy||copyMigrationActive||migrationRunning;AppendMenuW(menu,MF_STRING|(busy?MF_GRAYED:0),1,L"원본·대상 선택 후 검사");AppendMenuW(menu,MF_STRING|(copyMigrationPlan.empty()?MF_GRAYED:0),2,L"검사 결과 보기");AppendMenuW(menu,MF_STRING|(busy||copyMigrationPlan.empty()?MF_GRAYED:0),3,L"검사한 사본 복사");AppendMenuW(menu,MF_STRING|(busy?0:MF_GRAYED),4,L"진행 중 이관 중지");AppendMenuW(menu,MF_STRING|(busy?MF_GRAYED:0),5,L"복사 기록·연결·롤백");AppendMenuW(menu,MF_SEPARATOR,0,nullptr);AppendMenuW(menu,MF_STRING|(busy?MF_GRAYED:0),6,L"기존 이관 폴더 연결");AppendMenuW(menu,MF_STRING|(busy?MF_GRAYED:0),7,L"갤러리 연결 해제");AppendMenuW(menu,MF_STRING,8,L"이관 정보 저장");POINT point;GetCursorPos(&point);int choice=TrackPopupMenu(menu,TPM_RETURNCMD|TPM_NONOTIFY,point.x,point.y,0,hwnd,nullptr);DestroyMenu(menu);if(choice==1)inspectCopyMigration();else if(choice==2)MessageBoxW(hwnd,copyMigrationSummary().c_str(),L"읽기 전용 이관 검사",MB_OK|MB_ICONINFORMATION);else if(choice==3)applyCopyMigration();else if(choice==4){copyMigrationCancel=true;migrationCancel=true;status=L"이관 작업 중지 중…";}else if(choice==5)beginCopyMigration("history",json::object());else if(choice==6)attachMigration();else if(choice==7)detachMigrations();else if(choice==8)exportMigrationContext();}
